@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
    body {
        font-family: Inter, sans-serif;
    }
}

@layer components {
    .glass-header,
    .glass-header *,
    .glass-header *::before,
    .glass-header *::after {
        box-sizing: border-box !important;
    }

    .glass-header {
        @apply fixed top-0 left-0 right-0 w-full overflow-visible flex flex-col justify-center items-stretch;
        z-index: 99999;
        height: 56px;
        max-height: 56px;
        min-height: 54px;
        padding-top: 0;
        padding-bottom: 0;
        background: rgba(255, 255, 255, 0.85);
        backdrop-filter: blur(25px) saturate(200%);
        -webkit-backdrop-filter: blur(25px) saturate(200%);
        border-bottom: 1px solid rgba(255, 255, 255, 0.2);
        box-shadow: 0 4px 24px 0 rgba(31, 38, 135, 0.05);
        transition: background-color 0.14s cubic-bezier(0.4, 0, 0.2, 1),
            box-shadow 0.14s cubic-bezier(0.4, 0, 0.2, 1),
            border-color 0.14s cubic-bezier(0.4, 0, 0.2, 1);
        will-change: transform, background-color;
    }

    .glass-header .glass-header__shell {
        display: flex;
        align-items: center;
        flex: 1 1 auto;
        min-height: 0;
        min-width: 0;
        width: 100%;
    }

    .glass-header::before {
        content: "";
        @apply absolute inset-0 pointer-events-none;
        background: linear-gradient(135deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.05) 100%);
    }

    .glass-header-wrapper {
        @apply flex items-center justify-between w-full max-w-full flex-nowrap overflow-visible;
        height: 52px !important;
        min-height: 52px !important;
        max-height: 52px !important;
        padding: 0 clamp(12px, 2vw, 20px) 0 clamp(24px, 3vw, 40px) !important;
        gap: 16px;
        position: relative;
    }

    .glass-header-left { @apply flex items-center shrink-0 min-w-[80px]; gap: 15px !important; }
    .glass-header-center {
        @apply flex flex-1 min-w-0 max-w-[800px] mx-auto items-center self-center;
    }
    .glass-header-nav { @apply flex items-center shrink-0 whitespace-nowrap ml-5; gap: 10px !important; }
    .glass-header-right { @apply flex items-center shrink-0 flex-nowrap relative z-10; gap: 8px !important; }

    .glass-search-wrapper {
        @apply relative flex items-center w-full min-w-0 overflow-hidden rounded-[24px];
        background: rgba(255, 255, 255, 0.85) !important;
        backdrop-filter: blur(12px);
        -webkit-backdrop-filter: blur(12px);
        border: 1px solid rgba(255, 255, 255, 0.6);
        padding: 6px 6px 6px 18px;
        box-shadow: 0 1px 6px rgba(32, 33, 36, 0.2);
        min-height: 36px;
        max-height: 48px;
    }

    .glass-search-input {
        @apply flex-1 min-w-0 border-0 outline-none rounded-none bg-white text-black font-medium;
        padding: 12px 14px 12px 0;
        height: 36px;
        font-size: 16px;
        font-family: inherit;
        -webkit-text-fill-color: #000000 !important;
    }

    .glass-search-input::placeholder { color: #5f6368 !important; -webkit-text-fill-color: #5f6368 !important; }

    .glass-nav-btn,
    .glass-icon-btn {
        @apply inline-flex items-center justify-center rounded-full no-underline shrink-0;
        backdrop-filter: blur(15px);
        -webkit-backdrop-filter: blur(15px);
        border: 1.5px solid rgba(255, 255, 255, 0.5);
        background: rgba(255, 255, 255, 0.85);
        color: #333;
    }

    .glass-nav-btn { width: 36px; height: 36px; min-width: 36px; min-height: 36px; }
    .glass-icon-btn { width: 40px; height: 40px; min-width: 40px; min-height: 40px; }

    .glass-badge {
        @apply absolute inline-flex items-center justify-center text-white font-bold rounded-[10px];
        top: -8px;
        right: -8px;
        min-width: 20px;
        height: 20px;
        font-size: 12px;
        line-height: 1;
        padding: 0 6px;
        z-index: 20;
        background: linear-gradient(135deg, #ff6b6b 0%, #ee5a6f 100%);
        border: 2.5px solid rgba(255, 255, 255, 0.95);
    }

    .glass-dropdown {
        @apply rounded-xl p-2;
        z-index: 100002 !important;
        background: rgba(255, 255, 255, 0.95);
        backdrop-filter: blur(20px);
        -webkit-backdrop-filter: blur(20px);
        border: 1px solid rgba(255, 255, 255, 0.3);
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15), 0 0 0 1px rgba(0, 0, 0, 0.05);
        margin-top: 8px;
        min-width: 180px;
    }

    .glass-mobile-menu { @apply fixed inset-0 hidden pointer-events-none; z-index: 10000; }
    .glass-mobile-menu.active { @apply block pointer-events-auto; z-index: 100001; }
    .glass-mobile-menu-overlay { @apply absolute inset-0; background: rgba(0, 0, 0, 0.45); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); }
    .glass-mobile-menu-content {
        @apply absolute top-0 left-0 h-full overflow-y-auto overflow-x-hidden;
        width: min(320px, 88vw);
        max-width: 360px;
        background: rgba(255, 255, 255, 0.98);
        backdrop-filter: blur(24px);
        -webkit-backdrop-filter: blur(24px);
        box-shadow: 4px 0 40px rgba(0, 0, 0, 0.12), 0 0 1px rgba(0, 0, 0, 0.08);
        transform: translateX(-100%);
        transition: transform 0.2s cubic-bezier(0.32, 0.72, 0, 1);
    }
    .glass-mobile-menu.active .glass-mobile-menu-content { transform: translateX(0); }

    .glass-header.scrolled {
        background: rgba(255, 255, 255, 0.92);
        backdrop-filter: blur(30px) saturate(200%);
        -webkit-backdrop-filter: blur(30px) saturate(200%);
    }

    .header-top,
    .header-bottom,
    .header-menu,
    .header__top__wrapper {
        display: none !important;
    }
}

@media (max-width: 1199px) {
